#include "parksmart.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

void init_system(System *s){memset(s,0,sizeof(*s));s->nodes=8;s->next_id=1;for(int i=0;i<MAX_NODES;i++)for(int j=0;j<MAX_NODES;j++)s->graph[i][j]=i==j?0:INF;}
static void edge(System *s,int a,int b,int d){if(a>=0&&b>=0&&a<s->nodes&&b<s->nodes&&d>=0){s->graph[a][b]=d;s->graph[b][a]=d;}}
static void sample(System *s){const char *names[]={"Central Mall","Railway Station","City Hospital","Tech Park","Market Square","University","Stadium","Airport Road"};int cap[]={4,3,2,5,3,4,3,6};int rates[]={40,25,30,50,35,20,30,45};for(int i=0;i<8;i++){Space *p=&s->spaces[s->count++];p->id=i+1;p->node=i;p->capacity=cap[i];p->rate=rates[i];p->active=1;snprintf(p->name,sizeof(p->name),"%s",names[i]);}int roads[][3]={{0,1,4},{0,2,6},{1,3,5},{1,4,3},{2,4,2},{2,5,7},{3,6,4},{4,6,5},{4,5,3},{5,7,8},{6,7,4}};for(int i=0;i<11;i++)edge(s,roads[i][0],roads[i][1],roads[i][2]);}
int load_system(System *s,const char *dir){init_system(s);char path[512];snprintf(path,sizeof(path),"%s/spaces.csv",dir);FILE *f=fopen(path,"r");if(!f){sample(s);return 0;}char line[512];fgets(line,sizeof(line),f);while(fgets(line,sizeof(line),f)&&s->count<MAX_SPACES){Space p={0};if(sscanf(line,"%d,%d,%d,%d,%d,%d,%63[^\n]",&p.id,&p.node,&p.capacity,&p.occupied,&p.rate,&p.active,p.name)==7 && p.node>=0&&p.node<MAX_NODES&&p.capacity>0&&p.occupied>=0&&p.occupied<=p.capacity){s->spaces[s->count++]=p;if(p.node>=s->nodes)s->nodes=p.node+1;}}fclose(f);snprintf(path,sizeof(path),"%s/roads.csv",dir);f=fopen(path,"r");if(f){fgets(line,sizeof(line),f);while(fgets(line,sizeof(line),f)){int a,b,d;if(sscanf(line,"%d,%d,%d",&a,&b,&d)==3)edge(s,a,b,d);}fclose(f);}snprintf(path,sizeof(path),"%s/reservations.csv",dir);f=fopen(path,"r");if(f){fgets(line,sizeof(line),f);while(fgets(line,sizeof(line),f)&&s->rcount<MAX_RESERVATIONS){Reservation r={0};if(sscanf(line,"%d,%d,%d,%d,%d,%63[^\n]",&r.id,&r.space_id,&r.start,&r.end,&r.active,r.driver)==6){s->reservations[s->rcount++]=r;if(r.id>=s->next_id)s->next_id=r.id+1;}}fclose(f);}return 1;}
int save_system(const System *s,const char *dir){char path[512];snprintf(path,sizeof(path),"%s/spaces.csv",dir);FILE *f=fopen(path,"w");if(!f)return 0;fprintf(f,"id,node,capacity,occupied,rate,active,name\n");for(int i=0;i<s->count;i++){const Space *p=&s->spaces[i];fprintf(f,"%d,%d,%d,%d,%d,%d,%s\n",p->id,p->node,p->capacity,p->occupied,p->rate,p->active,p->name);}fclose(f);snprintf(path,sizeof(path),"%s/reservations.csv",dir);f=fopen(path,"w");if(!f)return 0;fprintf(f,"id,space_id,start,end,active,driver\n");for(int i=0;i<s->rcount;i++){const Reservation *r=&s->reservations[i];fprintf(f,"%d,%d,%d,%d,%d,%s\n",r->id,r->space_id,r->start,r->end,r->active,r->driver);}fclose(f);return 1;}
int available(const System *s,int idx,int start,int end){if(idx<0||idx>=s->count||start<0||end<=start)return 0;const Space *p=&s->spaces[idx];if(!p->active)return 0;int used=p->occupied;for(int i=0;i<s->rcount;i++){const Reservation *r=&s->reservations[i];if(r->active&&r->space_id==p->id&&start<r->end&&r->start<end)used++;}return used<p->capacity;}
int reserve_space(System *s,int id,const char *driver,int start,int end){if(!driver||!driver[0]||strchr(driver,',')||strchr(driver,'\n')||strlen(driver)>63||s->rcount>=MAX_RESERVATIONS)return -1;for(int i=0;i<s->count;i++)if(s->spaces[i].id==id){if(!available(s,i,start,end))return -2;Reservation *r=&s->reservations[s->rcount++];r->id=s->next_id++;r->space_id=id;r->start=start;r->end=end;r->active=1;snprintf(r->driver,sizeof(r->driver),"%s",driver);return r->id;}return -3;}
int cancel_reservation(System *s,int id){for(int i=0;i<s->rcount;i++)if(s->reservations[i].id==id&&s->reservations[i].active){s->reservations[i].active=0;return 1;}return 0;}
int shortest_paths(const System *s,int source,int dist[MAX_NODES]){if(source<0||source>=s->nodes)return 0;int seen[MAX_NODES]={0};for(int i=0;i<s->nodes;i++)dist[i]=INF;dist[source]=0;for(int k=0;k<s->nodes;k++){int u=-1;for(int i=0;i<s->nodes;i++)if(!seen[i]&&(u<0||dist[i]<dist[u]))u=i;if(u<0||dist[u]==INF)break;seen[u]=1;for(int v=0;v<s->nodes;v++)if(s->graph[u][v]<INF&&dist[u]+s->graph[u][v]<dist[v])dist[v]=dist[u]+s->graph[u][v];}return 1;}
int nearest_space(const System *s,int source,int start,int end,int *distance){int d[MAX_NODES];if(!shortest_paths(s,source,d))return -1;int best=-1;for(int i=0;i<s->count;i++)if(available(s,i,start,end)&&(best<0||d[s->spaces[i].node]<d[s->spaces[best].node]))best=i;if(distance)*distance=best<0?-1:d[s->spaces[best].node];return best<0||d[s->spaces[best].node]>=INF?-1:best;}
int greedy_assign(const System *s,const int *drivers,int nd,int start,int end,int *assignment,int *total){int taken[MAX_SPACES]={0},count=0;*total=0;for(int i=0;i<nd;i++){assignment[i]=-1;int dist[MAX_NODES];if(!shortest_paths(s,drivers[i],dist))continue;int best=-1;for(int j=0;j<s->count;j++)if(available(s,j,start,end)){int free_slots=s->spaces[j].capacity-s->spaces[j].occupied;for(int k=0;k<s->rcount;k++){const Reservation *r=&s->reservations[k];if(r->active&&r->space_id==s->spaces[j].id&&start<r->end&&r->start<end)free_slots--;}if(taken[j]>=free_slots)continue;if(best<0||dist[s->spaces[j].node]<dist[s->spaces[best].node])best=j;}if(best>=0&&dist[s->spaces[best].node]<INF){assignment[i]=s->spaces[best].id;taken[best]++;*total+=dist[s->spaces[best].node];count++;}}return count;}
/* Exact minimum-cost matching via successive shortest augmenting paths on a residual network. */
int optimal_assign(const System *s,const int *drivers,int nd,int start,int end,int *assignment,int *total){if(nd<0||nd>32)return -1;int slots[128],ns=0;for(int j=0;j<s->count&&ns<128;j++)if(available(s,j,start,end)){int free_slots=s->spaces[j].capacity-s->spaces[j].occupied;for(int k=0;k<s->rcount;k++){const Reservation *r=&s->reservations[k];if(r->active&&r->space_id==s->spaces[j].id&&start<r->end&&r->start<end)free_slots--;}while(free_slots-->0&&ns<128)slots[ns++]=j;}int N=nd+ns+2,source=N-2,sink=N-1;static int cap[164][164],cost[164][164];memset(cap,0,sizeof(cap));memset(cost,0,sizeof(cost));for(int i=0;i<nd;i++){assignment[i]=-1;cap[source][i]=1;int d[MAX_NODES];if(!shortest_paths(s,drivers[i],d))continue;for(int j=0;j<ns;j++){int length=d[s->spaces[slots[j]].node];if(length<INF){cap[i][nd+j]=1;cost[i][nd+j]=length;cost[nd+j][i]=-length;}}}for(int j=0;j<ns;j++)cap[nd+j][sink]=1;*total=0;int flow=0;for(;;){int d[164],parent[164],inqueue[164]={0},q[30000],head=0,tail=0;for(int i=0;i<N;i++)d[i]=INF,parent[i]=-1;d[source]=0;q[tail++]=source;inqueue[source]=1;while(head<tail){int u=q[head++];inqueue[u]=0;for(int v=0;v<N;v++)if(cap[u][v]>0&&d[u]!=INF&&d[u]+cost[u][v]<d[v]){d[v]=d[u]+cost[u][v];parent[v]=u;if(!inqueue[v]){q[tail++]=v;inqueue[v]=1;}}}if(parent[sink]<0)break;for(int v=sink;v!=source;v=parent[v]){int u=parent[v];cap[u][v]--;cap[v][u]++;}*total+=d[sink];flow++;}for(int i=0;i<nd;i++)for(int j=0;j<ns;j++)if(cap[nd+j][i]>0){assignment[i]=s->spaces[slots[j]].id;break;}return flow;}
